#!/usr/bin/env python3
"""gf180_corners.py -- one place that knows how to select a GF180 process corner in ngspice.

    from gf180_corners import header
    print(header("ss"))            # text to paste at the top of a deck

CLI:  python3 sim/env/gf180_corners.py        (re-writes sim/env/hdr_{tt,ss,ff,fs,sf}.spice)

A corner is a *set of .lib section names*, one per device family.  The global params that the
sections need (sw_stat_*, res_mc_skew, fnoicor) are set explicitly -- do NOT also .include design.ngspice.

  corner  MOS section   resistor      MOS cap       diode         MIM cap
  tt      typical       res_typical   moscap_typical diode_typical mimcap_typical
  ss      ss            res_ss        moscap_ss      diode_ss      mimcap_ss      slow: more R, more C, less current
  ff      ff            res_ff        moscap_ff      diode_ff      mimcap_ff      fast: less R, less C, more current
  fs      fs  (n fast, p slow)   passive = typical
  sf      sf  (n slow, p fast)   passive = typical

Temperature and supply are NOT part of the header: put `.temp <C>` and your own `vdd` source in the deck.
Digital-chip operating envelope: VDD 3.0/3.3/3.6 V, T = -40/27/125 C.
Slow-slow worst case = ss + 3.0 V + 125 C (speed) ; fast-fast worst case = ff + 3.6 V + -40 C (hold/overdrive).
"""
import os

PDK_LIB = "/foss/pdks/gf180mcuD/libs.tech/ngspice/sm141064.ngspice"
PASSIVES = {"tt": "typical", "ss": "ss", "ff": "ff", "fs": "typical", "sf": "typical"}
MOS = {"tt": "typical", "ss": "ss", "ff": "ff", "fs": "fs", "sf": "sf"}

def header(corner="tt", mim=False, bjt=False):
    if corner not in MOS:
        raise ValueError("corner must be one of tt ss ff fs sf")
    p = PASSIVES[corner]
    lines = [
        f"* ---- GF180 corner header: {corner} (generated by sim/env/gf180_corners.py) ----",
        ".param sw_stat_global=0 sw_stat_mismatch=0 mc_skew=3 res_mc_skew=3 cap_mc_skew=3 fnoicor=0",
        f".lib {PDK_LIB} {MOS[corner]}",
        f".lib {PDK_LIB} res_{p}",
        f".lib {PDK_LIB} moscap_{p}",
        f".lib {PDK_LIB} diode_{p}",
    ]
    if mim:
        lines.append(f".lib {PDK_LIB} mimcap_{p}")
    if bjt:
        lines.append(f".lib {PDK_LIB} bjt_{p}")
    lines.append("* ---- end header (add .temp and the supply yourself) ----")
    return "\n".join(lines) + "\n"

if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    for c in MOS:
        open(os.path.join(here, f"hdr_{c}.spice"), "w").write(header(c, mim=True))
        print("wrote", os.path.join(here, f"hdr_{c}.spice"))
